11765: format_retry     = [bool]($fr -and (Get-PropertyValue $fr 'attempted' $false) -eq $true)

    # ------------------------------------------------------------------------- format repair

    # The reviewer answered in prose instead of the JSON object: ONE repair turn resumes the
