            if ($identity.ProviderSource) { $repairArgv += @('-c', ('model_provider="' + (ConvertTo-TomlBasicString $identity.Provider) + '"')) }
            foreach ($ec in $extraConfig) { $repairArgv += @('-c', $ec) }
