        $repairParse = $null
        if (-not $repairProblem) {
            try {
                $repairParse = ConvertFrom-StructuredReply -Text $repairRaw -Purpose $Purpose -PriorFindings $priorInfo
                if (-not $repairParse.Valid) { $repairProblem = "still not valid: $($repairParse.ValidationError)" }
